INSERT INTO products (id, store_id, category_id, title, slug, description, price, stock, status, prep_time_minutes) VALUES
  ('00000000-0000-4000-e000-000000000001', '00000000-0000-4000-d000-000000000001', '00000000-0000-4000-c000-000000000001', 'Homemade Chocolate Chip Cookies (Dozen)', 'homemade-chocolate-chip-cookies-dozen-1', 'Freshly baked soft-batch chocolate chip cookies with premium butter. Perfect snack during class breaks.', 150, 5, 'ACTIVE', 30),
  ('00000000-0000-4000-e000-000000000002', '00000000-0000-4000-d000-000000000002', '00000000-0000-4000-c000-000000000001', 'Cold Brew Iced Caramel Latte (16oz)', 'cold-brew-iced-caramel-latte-16oz-2', 'Rich arabica cold brew coffee layered with salted caramel syrup and creamy fresh milk.', 100, 12, 'ACTIVE', 10),
  ('00000000-0000-4000-e000-000000000003', '00000000-0000-4000-d000-000000000003', '00000000-0000-4000-c000-000000000001', 'Matcha Cream Cheese Brownies (Box of 6)', 'matcha-cream-cheese-brownies-box-of-6-3', 'Fudgy matcha green tea brownies swirled with decadent cream cheese filling.', 190, 19, 'ACTIVE', 45),
  ('00000000-0000-4000-e000-000000000004', '00000000-0000-4000-d000-000000000004', '00000000-0000-4000-c000-000000000001', 'Crispy Siomai with Chili Garlic Oil (6 pcs)', 'crispy-siomai-with-chili-garlic-oil-6-pcs-4', 'Steamed and fried pork siomai served with signature homemade toasted chili garlic sauce and calamansi.', 80, 26, 'ACTIVE', 15),
  ('00000000-0000-4000-e000-000000000005', '00000000-0000-4000-d000-000000000005', '00000000-0000-4000-c000-000000000001', 'Iced Strawberry Hibiscus Tea (22oz)', 'iced-strawberry-hibiscus-tea-22oz-5', 'Refreshing brewed herbal hibiscus tea with real strawberry puree and chia seeds.', 95, 33, 'ACTIVE', 5),
  ('00000000-0000-4000-e000-000000000006', '00000000-0000-4000-d000-000000000006', '00000000-0000-4000-c000-000000000001', 'Artisan Ube Cheese Pandesal (Pack of 10)', 'artisan-ube-cheese-pandesal-pack-of-10-6', 'Fluffy purple yam bread stuffed with melting cheddar cheese cubes. Served warm.', 145, 40, 'ACTIVE', 20),
  ('00000000-0000-4000-e000-000000000007', '00000000-0000-4000-d000-000000000007', '00000000-0000-4000-c000-000000000001', 'Mango Graham Float Cups (350ml)', 'mango-graham-float-cups-350ml-7', 'Layers of crushed honey grahams, sweet condensed cream, and ripe Guimaras mangoes in convenient cup.', 115, 7, 'ACTIVE', 15),
  ('00000000-0000-4000-e000-000000000008', '00000000-0000-4000-d000-000000000008', '00000000-0000-4000-c000-000000000001', 'Gourmet Spam Musubi with Japanese Furikake', 'gourmet-spam-musubi-with-japanese-furikake-8', 'Teriyaki-glazed luncheon meat over seasoned sushi rice wrapped in nori seaweed.', 60, 14, 'ACTIVE', 10),
  ('00000000-0000-4000-e000-000000000009', '00000000-0000-4000-d000-000000000009', '00000000-0000-4000-c000-000000000002', 'Handcrafted Canvas Tote Bag (Laptop Sized)', 'handcrafted-canvas-tote-bag-laptop-sized-9', 'Heavy-duty 14oz cotton canvas tote with zipper and inside pocket. Custom silkscreen printed.', 285, 21, 'ACTIVE', 0),
  ('00000000-0000-4000-e000-00000000000a', '00000000-0000-4000-d000-00000000000a', '00000000-0000-4000-c000-000000000002', 'Crochet Sunflower Keychain & Bag Charm', 'crochet-sunflower-keychain-bag-charm-10', 'Lovingly hand-crocheted milk cotton sunflower with sturdy metal lobster clasp.', 105, 28, 'ACTIVE', 60),
  ('00000000-0000-4000-e000-00000000000b', '00000000-0000-4000-d000-00000000000b', '00000000-0000-4000-c000-000000000002', 'Custom Resin Letter Keychain with Gold Flakes', 'custom-resin-letter-keychain-with-gold-flakes-11', 'Crystal clear epoxy resin alphabet keychain embedded with dried baby''s breath and foil accents.', 125, 35, 'ACTIVE', 120),
  ('00000000-0000-4000-e000-00000000000c', '00000000-0000-4000-d000-00000000000c', '00000000-0000-4000-c000-000000000002', 'Woven Macrame Cup Sleeve & Strap', 'woven-macrame-cup-sleeve-strap-12', 'Eco-friendly handmade cotton cord drink holder for tumblers and boba cups.', 150, 42, 'ACTIVE', 30),
  ('00000000-0000-4000-e000-00000000000d', '00000000-0000-4000-d000-00000000000d', '00000000-0000-4000-c000-000000000002', 'Beaded Pearl Phone Charm Wristlet', 'beaded-pearl-phone-charm-wristlet-13', 'Durable nylon cord lanyard with iridescent beads and cute pastel stars.', 110, 9, 'ACTIVE', 20),
  ('00000000-0000-4000-e000-00000000000e', '00000000-0000-4000-d000-00000000000e', '00000000-0000-4000-c000-000000000002', 'Hand-poured Soy Candle (Lavender & Sage)', 'hand-poured-soy-candle-lavender-sage-14', '100% natural soy wax in 150g amber jar with cotton wick. Burns clean for 30+ hours.', 250, 16, 'ACTIVE', 0),
  ('00000000-0000-4000-e000-00000000000f', '00000000-0000-4000-d000-00000000000f', '00000000-0000-4000-c000-000000000003', 'LYFJSHS Campus Minimalist Lanyard & Card Case', 'lyfjshs-campus-minimalist-lanyard-card-case-15', 'Thick satin lanyard with leather accent and clear ID badge holder. Official campus colors.', 120, 23, 'ACTIVE', 0),
  ('00000000-0000-4000-e000-000000000010', '00000000-0000-4000-d000-000000000010', '00000000-0000-4000-c000-000000000003', 'Senior High Strand Embroidered Bucket Hat', 'senior-high-strand-embroidered-bucket-hat-16', '100% cotton twill bucket hat with minimalist strand initials embroidered on front.', 295, 30, 'ACTIVE', 0),
  ('00000000-0000-4000-e000-000000000011', '00000000-0000-4000-d000-000000000011', '00000000-0000-4000-c000-000000000003', 'Oversized ''Puyat for the Future'' Graphic Shirt', 'oversized-puyat-for-the-future-graphic-shirt-17', '220 GSM heavyweight combed cotton tee with breathable screen-printed student art.', 390, 37, 'ACTIVE', 0),
  ('00000000-0000-4000-e000-000000000012', '00000000-0000-4000-d000-000000000012', '00000000-0000-4000-c000-000000000003', 'Matte Vinyl Campus Sticker Pack (10 Pieces)', 'matte-vinyl-campus-sticker-pack-10-pieces-18', 'Waterproof and scratchproof die-cut vinyl stickers for hydroflasks, laptops, and binders.', 90, 44, 'ACTIVE', 0),
  ('00000000-0000-4000-e000-000000000013', '00000000-0000-4000-d000-000000000013', '00000000-0000-4000-c000-000000000003', 'Insulated Stainless Steel Campus Tumbler (750ml)', 'insulated-stainless-steel-campus-tumbler-750ml-19', 'Double-wall vacuum insulated water bottle keeping drinks icy cold for 24 hours.', 440, 11, 'ACTIVE', 0),
