  ('00000000-0000-4000-e000-000000000065', '00000000-0000-4000-d000-000000000065', '00000000-0000-4000-c000-000000000002', 'Hand-poured Soy Candle (Lavender & Sage) (Batch #4)', 'hand-poured-soy-candle-lavender-sage-batch-4-101', '100% natural soy wax in 150g amber jar with cotton wick. Burns clean for 30+ hours.', 230, 25, 'ACTIVE', 0),
  ('00000000-0000-4000-e000-000000000066', '00000000-0000-4000-d000-000000000066', '00000000-0000-4000-c000-000000000003', 'LYFJSHS Campus Minimalist Lanyard & Card Case (Batch #4)', 'lyfjshs-campus-minimalist-lanyard-card-case-batch-4-102', 'Thick satin lanyard with leather accent and clear ID badge holder. Official campus colors.', 135, 32, 'ACTIVE', 0),
  ('00000000-0000-4000-e000-000000000067', '00000000-0000-4000-d000-000000000067', '00000000-0000-4000-c000-000000000003', 'Senior High Strand Embroidered Bucket Hat (Batch #4)', 'senior-high-strand-embroidered-bucket-hat-batch-4-103', '100% cotton twill bucket hat with minimalist strand initials embroidered on front.', 310, 39, 'ACTIVE', 0),
  ('00000000-0000-4000-e000-000000000068', '00000000-0000-4000-d000-000000000068', '00000000-0000-4000-c000-000000000003', 'Oversized ''Puyat for the Future'' Graphic Shirt (Batch #4)', 'oversized-puyat-for-the-future-graphic-shirt-batch-4-104', '220 GSM heavyweight combed cotton tee with breathable screen-printed student art.', 405, 6, 'ACTIVE', 0),
  ('00000000-0000-4000-e000-000000000069', '00000000-0000-4000-d000-000000000069', '00000000-0000-4000-c000-000000000003', 'Matte Vinyl Campus Sticker Pack (10 Pieces) (Batch #4)', 'matte-vinyl-campus-sticker-pack-10-pieces-batch-4-105', 'Waterproof and scratchproof die-cut vinyl stickers for hydroflasks, laptops, and binders.', 105, 13, 'ACTIVE', 0),
  ('00000000-0000-4000-e000-00000000006a', '00000000-0000-4000-d000-000000000001', '00000000-0000-4000-c000-000000000003', 'Insulated Stainless Steel Campus Tumbler (750ml) (Batch #4)', 'insulated-stainless-steel-campus-tumbler-750ml-batch-4-106', 'Double-wall vacuum insulated water bottle keeping drinks icy cold for 24 hours.', 420, 20, 'ACTIVE', 0),
  ('00000000-0000-4000-e000-00000000006b', '00000000-0000-4000-d000-000000000002', '00000000-0000-4000-c000-000000000004', 'Comprehensive Calculus & STEM Review Notes (Digitized) (Batch #4)', 'comprehensive-calculus-stem-review-notes-digitized-batch-4-107', 'High-yield summarized handwritten review notes with step-by-step solved formulas.', 125, 27, 'ACTIVE', 0),
  ('00000000-0000-4000-e000-00000000006c', '00000000-0000-4000-d000-000000000003', '00000000-0000-4000-c000-000000000004', 'Hardbound Grid Bullet Journal Notebook (160 Pages) (Batch #4)', 'hardbound-grid-bullet-journal-notebook-160-pages-batch-4-108', '120 GSM bleed-resistant dotted ivory paper with elastic closure band and ribbon bookmark.', 205, 34, 'ACTIVE', 0),
  ('00000000-0000-4000-e000-00000000006d', '00000000-0000-4000-d000-000000000004', '00000000-0000-4000-c000-000000000004', 'Pastel Gel Ink Retractable Pens (Set of 6) (Batch #4)', 'pastel-gel-ink-retractable-pens-set-of-6-batch-4-109', 'Smooth-writing 0.5mm quick-dry Japanese ink in vintage aesthetic barrel colors.', 155, 41, 'ACTIVE', 0),
  ('00000000-0000-4000-e000-00000000006e', '00000000-0000-4000-d000-000000000005', '00000000-0000-4000-c000-000000000004', 'Aesthetic Sticky Notes & Index Tabs Bundle (Batch #4)', 'aesthetic-sticky-notes-index-tabs-bundle-batch-4-110', '6 pads of neutral pastel sticky notes and translucent PET film page flags.', 85, 8, 'ACTIVE', 0),
  ('00000000-0000-4000-e000-00000000006f', '00000000-0000-4000-d000-000000000006', '00000000-0000-4000-c000-000000000004', 'Accounting & General Mathematics Quick Formula Cards (Batch #4)', 'accounting-general-mathematics-quick-formula-cards-batch-4-111', 'Laminated flashcard ring with essential financial equations and algebra shortcuts.', 115, 15, 'ACTIVE', 0),
  ('00000000-0000-4000-e000-000000000070', '00000000-0000-4000-d000-000000000007', '00000000-0000-4000-c000-000000000005', 'Custom Org Poster & Event Layout Design (Batch #4)', 'custom-org-poster-event-layout-design-batch-4-112', 'Professional high-res digital poster, banner, and pubmat design delivered in PSD/PNG.', 380, 22, 'ACTIVE', 180),
  ('00000000-0000-4000-e000-000000000071', '00000000-0000-4000-d000-000000000008', '00000000-0000-4000-c000-000000000006', 'Mechanical Keyboard Lube & Switch Modding Service (Batch #4)', 'mechanical-keyboard-lube-switch-modding-service-batch-4-113', 'Full Krytox 205g0 lubing and stabilizer holee-modding service for buttery smooth typing.', 250, 29, 'ACTIVE', 240),
  ('00000000-0000-4000-e000-000000000072', '00000000-0000-4000-d000-000000000009', '00000000-0000-4000-c000-000000000005', 'Thrifted Vintage Corduroy Jacket (Unisex Oversized) (Batch #4)', 'thrifted-vintage-corduroy-jacket-unisex-oversized-batch-4-114', 'Handpicked, washed, and sanitized retro 90s corduroy button-up jacket. Fits S-L.', 395, 36, 'ACTIVE', 0),
  ('00000000-0000-4000-e000-000000000073', '00000000-0000-4000-d000-00000000000a', '00000000-0000-4000-c000-000000000006', 'Custom 3D Printed Laptop Stand & Phone Dock (Batch #4)', 'custom-3d-printed-laptop-stand-phone-dock-batch-4-115', 'Ergonomic dual-angle matte black PLA filament desk stand with cable organizer slot.', 190, 43, 'ACTIVE', 120)
