-- ============================================================================
-- Project Kita — Comprehensive Database Seed Script (100+ rows per table)
-- Run this in your Supabase SQL Editor to populate all tables for demo/showcase.
-- Dashboard URL: https://supabase.com/dashboard/project/nrloqmqweqczckgvjcny/sql/new
-- ============================================================================

BEGIN;

-- 0. SCHEMA GRANTS & EXTENSIONS
CREATE EXTENSION IF NOT EXISTS pgcrypto;

GRANT USAGE ON SCHEMA public TO postgres, anon, authenticated, service_role;
GRANT ALL ON ALL TABLES IN SCHEMA public TO postgres, anon, authenticated, service_role;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO postgres, anon, authenticated, service_role;
GRANT ALL ON ALL ROUTINES IN SCHEMA public TO postgres, anon, authenticated, service_role;

-- 1. CLEAN RESET (Prevents duplicate key conflicts on code, email, slug, order numbers)
TRUNCATE TABLE 
  public.reports,
  public.notifications,
  public.reviews,
  public.fulfillments,
  public.payments,
  public.order_items,
  public.orders,
  public.cart_items,
  public.carts,
  public.product_images,
  public.products,
  public.stores,
  public.student_verifications,
  public.profiles,
  public.categories,
  public.campuses
CASCADE;

DELETE FROM auth.users WHERE email LIKE '%@projectkita.edu.ph' OR email LIKE '%@lyfjshs.edu.ph';

-- 2. CAMPUSES
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, code = EXCLUDED.code;

-- Ensure RLS on Campuses and Categories
ALTER TABLE campuses ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN
  CREATE POLICY "Campuses viewable by everyone" ON campuses FOR SELECT USING (true);
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

ALTER TABLE categories ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN
  CREATE POLICY "Categories viewable by everyone" ON categories FOR SELECT USING (true);
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

-- 3. CATEGORIES
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name;

