-- 5. PROFILES
ON CONFLICT (id) DO UPDATE SET full_name = EXCLUDED.full_name, role = EXCLUDED.role;

-- 6. STUDENT VERIFICATIONS
ON CONFLICT (id) DO NOTHING;

-- 7. STORES
ON CONFLICT (id) DO NOTHING;

-- 8. PRODUCTS
ON CONFLICT (id) DO NOTHING;

-- 9. PRODUCT IMAGES
ON CONFLICT (id) DO NOTHING;

-- 10. CARTS & CART ITEMS
ON CONFLICT (user_id) DO UPDATE SET id = EXCLUDED.id, store_id = EXCLUDED.store_id;

ON CONFLICT (cart_id, product_id) DO UPDATE SET quantity = EXCLUDED.quantity;

-- 11. ORDERS
ON CONFLICT (id) DO UPDATE SET total_amount = EXCLUDED.total_amount, status = EXCLUDED.status;

-- 12. ORDER ITEMS
ON CONFLICT (id) DO NOTHING;

-- 13. PAYMENTS
ON CONFLICT (order_id) DO UPDATE SET payment_method = EXCLUDED.payment_method, reference_number = EXCLUDED.reference_number, receipt_url = EXCLUDED.receipt_url, status = EXCLUDED.status;

-- 14. FULFILLMENTS
ON CONFLICT (order_id) DO UPDATE SET method = EXCLUDED.method, location_details = EXCLUDED.location_details, preferred_time = EXCLUDED.preferred_time, notes = EXCLUDED.notes;

-- 15. REVIEWS
ON CONFLICT (order_id, product_id) DO UPDATE SET rating = EXCLUDED.rating, comment = EXCLUDED.comment;

-- 16. NOTIFICATIONS
ON CONFLICT (id) DO NOTHING;

-- 17. REPORTS
ON CONFLICT (id) DO NOTHING;

COMMIT;
